from qiskit.version import __version__

class Backend(ABC):
    """Abstract base class for backend modules."""

    @abstractmethod
    def quantum_operation(self, circuit):
        """Perform a quantum operation on the given circuit."""
        pass

    @abstractmethod
    def available_gates(self):
        """Return the available quantum gates supported by the backend."""
        pass

    @abstractmethod
    def max_qubits(self):
        """Return the maximum number of qubits supported by the backend."""
        pass

    def backend_version(self):
        """Return the version of the backend module."""
        return __version__
