```python
from bisect import insort

class DataStructure:
    def __init__(self):
        self.data = {}
        self.keys = []

    def insert(self, key, value):
        if key in self.data:
            raise ValueError("Key already exists")
        self.data[key] = value
        insort(self.keys, key)

    def get(self, key):
        if key not in self.data:
            raise ValueError("Key does not exist")
        return self.data[key]

    def delete(self, key):
        if key not in self.data:
            raise ValueError("Key does not exist")
        value = self.data.pop(key)
        self.keys.remove(key)
        return value

    def exists(self, key):
        return key in self.data

    def get_sorted_keys(self):
        return self.keys

    def num_elements(self):
        return len(self.data)

    def max_value_key(self):
        max_key = None
        max_value = float('-inf')
        for key, value in self.data.items():
            if value > max_value:
                max_value = value
                max_key = key
        return max_key

    def min_value_key(self):
        min_key = None
        min_value = float('inf')
        for key, value in self.data.items():
            if value < min_value:
                min_value = value
                min_key = key
        return min_key

    def average_value(self):
        if len(self.data) == 0:
            return 0
        return sum(self.data.values()) / len(self.data)

    def sum_values(self):
        return sum(self.data.values())
```

This implementation uses a dictionary `data` to store the key-value pairs and a sorted list `keys` to keep track of the order of the keys. The `insert` method inserts a new key-value pair into the dictionary and maintains the sorted order of the keys in the list. The `get` method retrieves the value associated with a given key. The `delete` method removes a key-value pair from the dictionary and updates the sorted list. The `exists` method checks if a key exists in the dictionary. The `get_sorted_keys` method returns a list of all the keys in sorted order. The `num_elements` method returns the number of elements in the data structure. The `max_value_key` and `min_value_key` methods iterate through all the key-value pairs to find the key with the maximum and minimum values, respectively. The `average_value` method calculates the average value of all the elements in the data structure. The `sum_values` method calculates the sum of all the values in the data structure.

