def generate_histogram(numbers):
    histogram = {}
    for num in numbers:
        if num % 3 == 0:
            if num in histogram:
                histogram[num] += 1
            else:
                histogram[num] = 1
    sorted_histogram = sorted(histogram.items(), key=lambda x: x[1], reverse=True)
    return sorted_histogram

def display_histogram(histogram):
    print("Histogram:")
    for num, frequency in histogram:
        print(f"{num}: {'*' * frequency}")

numbers = input("Enter the numbers (separated by spaces): ").split()
numbers = [int(num) for num in numbers]

histogram = generate_histogram(numbers)
display_histogram(histogram)
```

