```python
class Align:
    def __init__(self, text: str, alignment: str, width: int):
        self.text = text
        self.alignment = alignment
        self.width = width

    def renderable(self) -> str:
        if self.alignment == "left":
            return self.text.ljust(self.width)
        elif self.alignment == "right":
            return self.text.rjust(self.width)
        elif self.alignment == "center":
            return "\n".join(line.center(self.width) for line in self.text.split("\n"))

    def align(self) -> str:
        return self.alignment

def align_text(text: str, alignment: str, width: int) -> str:
    if alignment == "left":
        return text.ljust(width)
    elif alignment == "right":
        return text.rjust(width)
    elif alignment == "center":
        return "\n".join(line.center(width) for line in text.split("\n"))
```

