class ShoppingCart:
    def __init__(self):
        self.cart = []

    def add_item(self, item_name, item_price):
        self.cart.append((item_name, item_price))

    def remove_item(self, item_name):
        for item in self.cart:
            if item[0] == item_name:
                self.cart.remove(item)
                return
        print(f"{item_name} not found in the cart.")

    def calculate_total(self):
        total_cost = sum(item[1] for item in self.cart)
        return total_cost

    def display_cart(self):
        if not self.cart:
            print("The cart is empty.")
        else:
            print("Items in the cart:")
            for item in self.cart:
                print(f"{item[0]} - ${item[1]}")

# Example usage
cart = ShoppingCart()
cart.add_item("Shirt", 20)
cart.add_item("Pants", 30)
cart.add_item("Shoes", 50)
cart.display_cart()
print("Total cost:", cart.calculate_total())

cart.remove_item("Pants")
cart.display_cart()
print("Total cost:", cart.calculate_total())
```

