import ipaddress

def is_valid_ip_address(ip):
    try:
        ipaddress.ip_address(ip)
        return True
    except ValueError:
        return False

def is_valid_ipv6_address(ip):
    try:
        ipaddress.IPv6Address(ip)
        return True
    except ValueError:
        return False

def is_valid_compressed_ipv6_address(ip):
    try:
        ipaddress.IPv6Address(ip).compressed
        return True
    except ValueError:
