                else:
                    i += 1
            elif line[i:i+2] == '##':
                if not in_comment:
                    in_comment = True
                    line = line[:i]
                else:
                    i += 2
            elif line[i:i+2] == '##':
                if in_comment:
                    in_comment = False
                    line = line[i+2:]
                else:
                    i += 2
            else:
                i += 1
        new_code.append(line)
    return '\n'.join(new_code)

