        total_area += area(point, polygon_vertices[i], polygon_vertices[(i + 1) % n])
    polygon_area = 0
    for i in range(n):
        polygon_area += area(polygon_vertices[i], polygon_vertices[(i + 1) % n], polygon_vertices[(i + 2) % n])
    return abs(total_area - polygon_area) < 1e-6  # considering floating point precision

