```python
class Node:
    def __init__(self, data):
        self.left = None
        self.right = None
        self.data = data

def maxPathSum(node):
    if node is None:
        return 0
    else:
        leftSum = maxPathSum(node.left)
        rightSum = maxPathSum(node.right)
        maxSum = max(max(leftSum, rightSum) + node.data, node.data)
        maxRootSum = max(maxSum, leftSum + rightSum + node.data)
        return max(maxRootSum, node.data)
