To create a web service to convert temperatures from Celsius to Fahrenheit and handle invalid inputs, you can use any programming language or framework of your choice. Here's an example implementation using Python and Flask:

```python
from flask import Flask, request, jsonify

app = Flask(__name__)

def celsius_to_fahrenheit(temperature):
    return (temperature * 9/5) + 32

def is_valid_temperature(temperature):
    return -273.15 <= temperature <= 1000

def convert_temperatures(temperatures):
    valid_temperatures = []
    invalid_temperatures = []
    converted_temperatures = []

    for temperature in temperatures:
        if isinstance(temperature, (int, float)):
            if is_valid_temperature(temperature):
                valid_temperatures.append(temperature)
                converted_temperatures.append(round(celsius_to_fahrenheit(temperature), 1))
            else:
                invalid_temperatures.append(temperature)
                converted_temperatures.append("Invalid temperature")
        else:
            invalid_temperatures.append(temperature)
            converted_temperatures.append("Invalid temperature")

    return converted_temperatures, valid_temperatures, invalid_temperatures

@app.route('/convert', methods=['POST'])
def convert():
    temperatures = request.get_json()
    converted_temperatures, valid_temperatures, invalid_temperatures = convert_temperatures(temperatures)

    response = {
        "converted_temperatures": converted_temperatures,
        "valid_temperatures_count": len(valid_temperatures),
        "invalid_temperatures_count": len(invalid_temperatures)
    }

    return jsonify(response)

if __name__ == '__main__':
    app.run()
```

