import math

def pythagorean_theorem(side_a, side_b, side_c):
    # Check if the sides form a valid triangle
    if (side_a + side_b <= side_c) or (side_a + side_c <= side_b) or (side_b + side_c <= side_a):
        raise ValueError("The given sides do not form a valid triangle")

    # Check if the sides satisfy the triangle inequality theorem
    if (side_a <= 0) or (side_b <= 0) or (side_c <= 0):
        raise ValueError("The given sides do not satisfy the triangle inequality theorem")

    # Calculate and return the length of the missing side using the Pythagorean theorem
    if side_a**2 + side_b**2 == side_c**2:
        return math.sqrt(side_a**2 + side_b**2)
    elif side_a**2 + side_c**2 == side_b**2:
        return math.sqrt(side_a**2 + side_c**2)
    elif side_b**2 + side_c**2 == side_a**2:
        return math.sqrt(side_b**2 + side_c**2)
    else:
        raise ValueError("The given sides do not satisfy the Pythagorean theorem")
```

