        # Record a video for the specified duration
        self.recorded_video = f"Video Data ({duration} seconds)"

    def zoom_in(self, level: int):
        # Zoom in the camera by the specified level
        if level >= 0:
            self.zoom_level += level
        else:
            print("Invalid zoom level. Zoom level must be a non-negative integer.")

    def zoom_out(self, level: int):
