class CollegeStudent:
    def __init__(self, name, age, major):
        self.name = name
        self.age = age
        self.major = major
        self.courses_enrolled = []

    def add_course(self, course):
        if course in self.courses_enrolled:
            print(f"Warning: {course} is already enrolled.")
        else:
            self.courses_enrolled.append(course)

    def remove_course(self, course):
        if course not in self.courses_enrolled:
            print(f"Warning: {course} is not enrolled.")
        else:
            self.courses_enrolled.remove(course)

    def display_info(self):
        print("Student Information:")
        print(f"Name: {self.name}")
        print(f"Age: {self.age}")
        print(f"Major: {self.major}")
        print("Courses Enrolled:")
        for course in self.courses_enrolled:
            print(course)

    def calculate_total_credits(self):
        total_credits = 0
        for course in self.courses_enrolled:
            total_credits += course.credit_hours
        return total_credits

    def display_enrolled_courses_sorted(self):
        sorted_courses = sorted(self.courses_enrolled)
        print("Enrolled Courses (sorted alphabetically):")
        for course in sorted_courses:
            print(course)

    def display_enrolled_courses_by_major(self):
        courses_by_major = {}
        for course in self.courses_enrolled:
            if course.major not in courses_by_major:
                courses_by_major[course.major] = []
            courses_by_major[course.major].append(course)

        print("Enrolled Courses (grouped by major):")
        for major, courses in courses_by_major.items():
            print(f"Major: {major}")
            for course in courses:
                print(course)
```

In this implementation, the class `CollegeStudent` has an `__init__` method to initialize the attributes `name`, `age`, `major`, and `courses_enrolled` (which is initialized as an empty list).

The `add_course` method checks if the course is already in the `courses_enrolled` list, and if not, it adds the course to the list. If the course is already enrolled, it displays a warning message.

