import random

class Account:
    def __init__(self, name, initial_balance, pin):
        self.account_number = str(random.randint(1000, 9999))
        self.name = name
        self.balance = initial_balance
        self.pin = pin

class BankingSystem:
    def __init__(self):
        self.accounts = {}

    def create_account(self, name, initial_balance, pin):
        account = Account(name, initial_balance, pin)
        self.accounts[account.account_number] = account
        return account.account_number

    def deposit(self, account_number, amount):
        if account_number in self.accounts:
            self.accounts[account_number].balance += amount
            return True
        return False

    def withdraw(self, account_number, amount):
        if account_number in self.accounts and self.accounts[account_number].balance >= amount:
            self.accounts[account_number].balance -= amount
            return True
        return False

    def check_balance(self, account_number):
        if account_number in self.accounts:
            return self.accounts[account_number].balance
        return 0

    def authenticate(self, account_number, pin):
        if account_number in self.accounts and self.accounts[account_number].pin == pin:
            return True
        return False

# Example usage
bank = BankingSystem()
acc_num = bank.create_account("John Doe", 1000, "1234")
print(bank.deposit(acc_num, 500))  # True
print(bank.check_balance(acc_num))  # 1500
print(bank.withdraw(acc_num, 200))  # True
print(bank.check_balance(acc_num))  # 1300
print(bank.authenticate(acc_num, "1234"))  # True
print(bank.authenticate(acc_num, "0000"))  # False
```

