```python
def parse_ip_addresses(ip_string):
    ip_addresses = []
    current_address = ''

    for char in ip_string:
        if char.isdigit():
            current_address += char
        elif char == ',':
            if current_address:
                ip_addresses.append(current_address)
            current_address = ''
        elif char == '.':
            if current_address and int(current_address) <= 255:
                current_address += char
            else:
                raise ValueError('Invalid IP address')
        elif char.isspace():
            continue
        else:
            raise ValueError('Invalid IP address')

    if current_address:
        ip_addresses.append(current_address)

    valid_ip_addresses = []
    for address in ip_addresses:
        if len(address) <= 12:
            address_parts = address.split('.')
            if len(address_parts) == 4:
                valid = True
                for part in address_parts:
                    if not part.isdigit() or int(part) > 255:
                        valid = False
                        break
                if valid:
                    valid_ip_addresses.append(address)

    return valid_ip_addresses
```

