```python
class NotAllowed(Exception):
    """Raised when attempting to change class.id"""


class DatabaseException(Exception):
    """Raised for database errors"""


class ColumnTypeUnknown(Exception):
    """Raised when an unknown column type is specified"""


class Database:
    def __init__(self):
        self.__tables = {}

    def create_table(self, table_name, columns):
        if table_name in self.__tables:
            raise DatabaseException("Table already exists")
        for col_type in columns.values():
            if col_type not in ['int', 'str', 'float']:
                raise ColumnTypeUnknown("Unknown column type")
        self.__tables[table_name] = []

    def insert_record(self, table_name, record):
        if table_name not in self.__tables:
            raise DatabaseException("Table does not exist")
        self.__tables[table_name].append(record)

    def query(self, table_name, condition):
        if table_name not in self.__tables:
            raise DatabaseException("Table does not exist")
        column, op, value = condition.split()
        records = self.__tables[table_name]
        if op == '=':
            return [record for record in records if record.get(column) == value]
        elif op == '>':
            return [record for record in records if record.get(column) > value]
        elif op == '<':
            return [record for record in records if record.get(column) < value]
        elif op == '>=':
            return [record for record in records if record.get(column) >= value]
        elif op == '<=':
            return [record for record in records if record.get(column) <= value]
        else:
            raise DatabaseException("Invalid condition operator")
```

