```python
class BasePoints:
    def __init__(self, x, y, z):
        self.x = x
        self.y = y
        self.z = z

    def distance_to_origin(self):
        return (self.x ** 2 + self.y ** 2 + self.z ** 2) ** 0.5


class CameraPoints(BasePoints):
    def __init__(self, x, y, z, image_coordinates):
        super().__init__(x, y, z)
        self.image_coordinates = image_coordinates

    def project_to_image_plane(self):
        return self.image_coordinates


class DepthPoints(BasePoints):
    def __init__(self, x, y, z, depth_value):
        super().__init__(x, y, z)
        self.depth_value = depth_value

    def calculate_depth_difference(self, other_point):
        return abs(self.depth_value - other_point.depth_value)


class LiDARPoints(BasePoints):
    def __init__(self, x, y, z, intensity):
        super().__init__(x, y, z)
        self.intensity = intensity

    def calculate_intensity_difference(self, other_point):
        return abs(self.intensity - other_point.intensity)
```

