def merge_and_compare(dict1, dict2):
    result = {}
    for key in set(dict1.keys()).union(dict2.keys()):
        if key in dict1 and key in dict2:
            result[key] = abs(dict1[key] - dict2[key])
        elif key in dict1: 
            result[key] = dict1[key]
        else:
            result[key] = dict2[key]
    return result

