```python
def fahrenheit_to_kelvin(fahrenheit):
    """
    Convert Fahrenheit to Kelvin
    """
    return round(((fahrenheit - 32) * 5 / 9) + 273.15, 2)

def process_temperatures(input_file, output_file):
    """
    Read temperatures in Fahrenheit from input file, 
    convert them to Kelvin and write the results to output file
    """
    try:
        with open(input_file, 'r') as ifile, open(output_file, 'w') as ofile:
            for line in ifile:
                try:
                    fahrenheit = float(line.strip())
                    kelvin = fahrenheit_to_kelvin(fahrenheit)
                    ofile.write(f"The temperature in Fahrenheit is {fahrenheit} and in Kelvin is {kelvin}\n")
                except ValueError:
                    ofile.write(f"Invalid temperature value: {line}\n")
    except FileNotFoundError:
        print("The input file does not exist.")
    except Exception as e:
        print(f"An error occurred: {e}")

process_temperatures('input.txt', 'output.txt')
```

