def convert_list_to_dict(lst):
    result = {}
    count = {}

    for element in lst:
        if element in result:
            count[element] += 1
            while element + count[element] in result:
                count[element] += 1
            result[element + count[element]] = 1
        else:
            result[element] = 1
            count[element] = 0

    return result
