Here is an implementation of the 'Shape' class in Python:

```python
class Shape:
    def __init__(self, length, width):
        self.length = length
        self.width = width

    def getArea(self, shapeType):
        if self.length <= 0 or self.width <= 0:
            return "Invalid input: Length and width must be positive integers."
        if shapeType == 'rectangle':
            return self.length * self.width
        elif shapeType == 'square':
            return self.length * self.length
        elif shapeType == 'triangle':
            return (self.length * self.width) / 2
        else:
            return "Invalid shape type."

    def getPerimeter(self, shapeType):
        if self.length <= 0 or self.width <= 0:
            return "Invalid input: Length and width must be positive integers."
        if shapeType == 'rectangle':
            return 2 * (self.length + self.width)
        elif shapeType == 'square':
            return 4 * self.length
        elif shapeType == 'triangle':
            return self.length + self.width + ((self.length ** 2 + self.width ** 2) ** 0.5)
        else:
            return "Invalid shape type."

    def getShapeType(self):
        if self.length <= 0 or self.width <= 0:
            return "Invalid input: Length and width must be positive integers."
        if self.length == self.width:
            return 'square'
        elif self.length != self.width:
            return 'rectangle'
        else:
            return 'triangle'
