```python
from typing import List

def get_hand_value(hand: List[str]) -> int:
    """
    Helper function to calculate the value of a hand.
    """
    value = 0
    num_aces = 0

    for card in hand:
        if card.isdigit():
            value += int(card)
        elif card in ['J', 'Q', 'K']:
            value += 10
        elif card == 'A':
            num_aces += 1

    for _ in range(num_aces):
        if value + 11 <= 21:
            value += 11
        else:
            value += 1

    return value

def play_blackjack(player_hand: List[str], dealer_hand: List[str]) -> str:
    player_value = get_hand_value(player_hand)
    dealer_value = get_hand_value(dealer_hand)

    if player_value == 21:
        return "Player"
    elif dealer_value == 21:
        return "Dealer"

    while True:
        if player_value > 21:
            return "Dealer"

        if player_value >= 17:
            break

        # Player hits
        card = input("Player, do you want to hit or stand? (H/S): ")
        if card == 'H':
            player_hand.append(card)
            player_value = get_hand_value(player_hand)
        else:
            break

    # Dealer reveals second card
    dealer_hand.append(dealer_hand[1])
    dealer_value = get_hand_value(dealer_hand)

    while dealer_value < 17:
        # Dealer hits
        dealer_hand.append(card)
        dealer_value = get_hand_value(dealer_hand)

    if dealer_value > 21:
        return "Player"
    elif dealer_value > player_value:
        return "Dealer"
    elif dealer_value < player_value:
        return "Player"
    else:
        return "Dealer"
```

You can call the `play_blackjack` function with the initial player and dealer hands to simulate a game of Blackjack.

