def max_product_with_negative(arr):
    if len(arr) < 3:
        return 0

    max1 = max2 = max3 = float('-inf')
    min1 = min2 = float('inf')

    for num in arr:
        if num > max1:
            max3 = max2
            max2 = max1
            max1 = num
        elif num > max2:
            max3 = max2
            max2 = num
        elif num > max3:
            max3 = num

        if num < min1:
            min2 = min1
            min1 = num
